<?php
namespace App\Services;
use App\Models\Order; use App\Models\Product; use App\Models\ProductVariant; use Illuminate\Support\Facades\DB; use RuntimeException;
class OrderService { public function commitStock(Order $order):void{if($order->stock_committed)return;DB::transaction(function()use($order){$order->load('items');foreach($order->items as $item){if($item->product_variant_id){$v=ProductVariant::lockForUpdate()->find($item->product_variant_id);if(!$v||$v->stock<$item->quantity)throw new RuntimeException("Insufficient variant stock for {$item->product_name}");$v->decrement('stock',$item->quantity);}else{$p=Product::lockForUpdate()->find($item->product_id);if(!$p||$p->stock<$item->quantity)throw new RuntimeException("Insufficient stock for {$item->product_name}");$p->decrement('stock',$item->quantity);}}$order->update(['stock_committed'=>true]);});}
public function releaseStock(Order $order):void{if(!$order->stock_committed)return;DB::transaction(function()use($order){$order->load('items');foreach($order->items as $item){if($item->product_variant_id){if($v=ProductVariant::lockForUpdate()->find($item->product_variant_id))$v->increment('stock',$item->quantity);}elseif($p=Product::lockForUpdate()->find($item->product_id))$p->increment('stock',$item->quantity);}$order->update(['stock_committed'=>false]);});}}
